create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique,created_at timestamptz not null default now());
create table if not exists public.messages(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,username text not null,content text not null check(char_length(content) between 1 and 500),created_at timestamptz not null default now());
create table if not exists public.notifications(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text not null,read boolean not null default false,created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.messages enable row level security; alter table public.notifications enable row level security;
drop policy if exists profiles_select on public.profiles; create policy profiles_select on public.profiles for select to authenticated using(true);
drop policy if exists profiles_insert on public.profiles; create policy profiles_insert on public.profiles for insert to authenticated with check(auth.uid()=id);
drop policy if exists profiles_update on public.profiles; create policy profiles_update on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists messages_select on public.messages; create policy messages_select on public.messages for select to authenticated using(true);
drop policy if exists messages_insert on public.messages; create policy messages_insert on public.messages for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists notifications_select on public.notifications; create policy notifications_select on public.notifications for select to authenticated using(auth.uid()=user_id);
drop policy if exists notifications_update on public.notifications; create policy notifications_update on public.notifications for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare u text; begin u:=coalesce(nullif(new.raw_user_meta_data->>'username',''),split_part(new.email,'@',1)); insert into public.profiles(id,username) values(new.id,u) on conflict(username) do update set username=u||'_'||substr(new.id::text,1,6); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
do $$ begin begin alter publication supabase_realtime add table public.messages; exception when duplicate_object then null; end; end $$;
